/* Skip navigation for keyboard users */
.skip-nav {
  position: absolute;
  top: -40px;
  left: 0;
  background: #000000;
  color: #ffffff;
  padding: 8px;
  text-decoration: none;
  border-radius: 0 0 4px 0;
  z-index: 100;
  transition: top 0.2s ease;
}

.skip-nav:focus {
  top: 0;
}

/* Main content area */
.coming-soon-main {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
  background: #ffffff;
}

.coming-soon-container {
  max-width: 600px;
  width: 100%;
  text-align: center;
  animation: fadeInUp 0.8s ease-out;
}

.coming-soon-title {
  font-size: clamp(1.75rem, 5vw, 2.5rem);
  color: #1a1a1a;
  margin-bottom: 1.5rem;
  font-weight: 700;
  line-height: 1.2;
}

.coming-soon-description {
  color: #4a4a4a;
  font-size: 1.125rem;
  margin-bottom: 1rem;
}

/* Contact section */
.contact-section {
  margin-top: 2rem;
  padding-top: 2rem;
  border-top: 1px solid #e0e0e0;
}

.contact-heading {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: #1a1a1a;
}

.contact-info {
  color: #4a4a4a;
  font-size: 1.125rem;
  margin-bottom: 1rem;
}

/* Enhanced focus indicators */
.contact-link {
  color: #0066cc;
  text-decoration: underline;
  text-underline-offset: 2px;
  transition: all 0.2s ease;
  display: inline-block;
  padding: 2px 4px;
  border-radius: 3px;
}

.contact-link:hover {
  background-color: #f0f8ff;
  text-decoration-thickness: 2px;
}

.contact-link:focus {
  outline: 3px solid #0066cc;
  outline-offset: 2px;
  background-color: #f0f8ff;
}

/* Animation */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Dark mode support */
@media (prefers-color-scheme: dark) {
  .coming-soon-main {
    background: #0a0a0a;
  }

  .coming-soon-title {
    color: #ffffff;
  }

  .coming-soon-description,
  .contact-info {
    color: #b0b0b0;
  }

  .contact-heading {
    color: #ffffff;
  }

  .contact-section {
    border-top-color: #2a2a2a;
  }

  .contact-link {
    color: #4da3ff;
  }

  .contact-link:hover,
  .contact-link:focus {
    background-color: rgba(77, 163, 255, 0.1);
  }

  .contact-link:focus {
    outline-color: #4da3ff;
  }
}

/* Responsive adjustments */
@media (max-width: 600px) {
  .coming-soon-container {
    padding: 0 20px;
  }

  .coming-soon-title {
    font-size: 1.75rem;
  }

  .coming-soon-description,
  .contact-info {
    font-size: 1rem;
  }
}

/* High contrast mode support */
@media (prefers-contrast: high) {
  .coming-soon-main {
    background: #ffffff;
  }

  .coming-soon-title,
  .contact-heading {
    color: #000000;
  }

  .contact-link {
    color: #0000ee;
  }

  .contact-link:focus {
    outline-color: #000000;
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }

  .coming-soon-container {
    animation: none;
  }
}

