.ligthning {
  filter: drop-shadow(8px 8px 0 #0005);
  animation: animateLigthning 2s steps(1) infinite;
}

@keyframes animateLigthning {
  0% {
    filter: drop-shadow(8px 8px 0 #0001) drop-shadow(0 0 0 #fff) brightness(1);
  }
  95% {
    filter: drop-shadow(8px 8px 0 #0001) drop-shadow(0 0 50px #fff5)
      brightness(10);
  }
}

.ligthning::before {
  content: "";
  position: absolute;
  top: -50px;
  left: 40px;
  width: 110px;
  height: 110px;
  border-radius: 50%;
  background: #484f59;
  box-shadow: 90px -10px 0 30px #484f59;
}

.ligthning::after {
  content: "";
  position: absolute;
  inset: 0;
  background: #484f59;
  border-radius: 100px;
  z-index: 1;
}

.ligthning .drop {
  position: absolute;
  top: 40px;
  background: #05a2eb;
  width: 2px;
  height: 10px;
  transform-origin: bottom;
  animation: animate 2s linear infinite;
}

@keyframes animate {
  0% {
    transform: translateY(0) scaleY(1);
  }
  70% {
    transform: translateY(360px) scaleY(1);
  }
  80% {
    transform: translateY(360px) scaleY(0.2);
  }
  100% {
    transform: translateY(360px) scaleY(0) scaleX(15);
  }
}

