export const IS_PRODUCTION = process.env.NODE_ENV === "production";
export const BASE_HOST = IS_PRODUCTION
  ? process.env.NEXT_PUBLIC_API_HOST
  : "http://localhost";
export const BACKEND_PORT = process.env.NEXT_PUBLIC_BACKEND_PORT || 8000;
export const API_VERSION = "v1";

export const BASE_URL = `${BASE_HOST}:${BACKEND_PORT}`;
export const PATH_URL = 'site';
export const API_URL = `${BASE_URL}/api/${API_VERSION}/${PATH_URL}`;

const USE_MOCKS = true;
import { API_URL } from "./config";

/**
 * Unified HTTP request utility
 * @param {string} endpoint - Endpoint relative to API_URL (no leading slash)
 * @param {object} options - Fetch options (method, headers, body, token, etc.)
 */
const httpRequest = async (endpoint, api_url = API_URL, options = {}) => {
  if (USE_MOCKS) {
    console.warn(`🧩 [MOCK_MODE] Fetch skipped for ${endpoint}`);
    throw new Error("MOCK_MODE_ENABLED");
  }

  const url = `${api_url}/${endpoint}`;
  const { token: customToken, method = "GET", body, headers = {} } = options;

  // Optional: try to pull token automatically from localStorage
  const storedToken =
    typeof window !== "undefined" ? localStorage.getItem("auth_token") : null;
  const token = customToken || storedToken;

  const config = {
    method,
    headers: {
      "Content-Type": "application/json",
      ...(token && { Authorization: `Bearer ${token}` }),
      ...headers,
    },
    ...(body && { body: JSON.stringify(body) }),
  };

  const response = await fetch(url, config);

  // ✅ Solo leemos el body una vez
  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`HTTP ${response.status}: ${errorText}`);
  }

  // ✅ Solo retornamos JSON una vez
  return await response.json();

  // if (!response.ok) {
  //   let errorBody;
  //   try {
  //     errorBody = await response.json();
  //   } catch {
  //     errorBody = await response.text();
  //   }
  //
  //   const error = new Error(
  //     `🔴 HTTP ${response.status}: ${response.statusText}`
  //   );
  //   error.status = response.status;
  //   error.body = errorBody;
  //   throw error;
  // }
  //
  // const contentType = response.headers.get("content-type");
  // return contentType?.includes("application/json")
  //   ? response.json()
  //   : response.text();
};

export default httpRequest;

