"use client";

import "./styles.css";

import { useMotionValue } from "framer-motion";
import { useRef } from "react";

import Link from "next/link";

import { FramerImage } from "@/atoms/hocs";

export const MovingImage = ({ title, img, link }) => {
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const imgRef = useRef(null);

  const handleMouse = (event) => {
    imgRef.current.style.display = "inline-block";
    x.set(event.pageX - 100);
    y.set(-10);
  };

  const handleMouseLeave = () => {
    imgRef.current.style.display = "none";
    x.set(0);
    y.set(0);
  };

  return (
    <Link
      href={link}
      target="_blank"
      onMouseMove={handleMouse}
      onMouseLeave={handleMouseLeave}
    >
      <h2 className="moving-image_link">{title}</h2>

      <FramerImage
        ref={imgRef}
        src={img}
        alt={title}
        className="moving-image_frame"
        style={{ x: x, y: y }}
        initial={{ opacity: 0 }}
        whileInView={{ opacity: 1, transition: { duration: 0.2 } }}
      />
    </Link>
  );
};

.moving-image_link {
  @apply capitalize text-xl font-semibold hover:underline;
}

.moving-image_frame {
  @apply z-10 w-96 h-auto hidden absolute rounded-lg;
}

