.skill:before {
  content: "";
  position: absolute;
  bottom: 100;
  left: 100;
  right: 100;
  top: 100;
  border: 1px solid #fff;
  border-radius: 50%;
  width: 4.5rem;
  height: 4.5rem;
  z-index: -1;
  box-shadow:
    0 0 50px #0f0,
    inset 0 0 50px #0f0;
  -webkit-box-reflect: below 10px
    linear-gradient(transparent, transparent, #0002);

  animation: fireRing 5s linear infinite;
  @apply bg-dark
  border-primary
  opacity-90
  hover:opacity-100
  hover:bg-light;
}

@keyframes fireRing {
  0% {
    box-shadow:
      0 0 50px #0f0,
      inset 0 0 50px #0f0;
    filter: hue-rotate(0deg);
  }

  20% {
    box-shadow:
      0 0 60px #0f0,
      inset 0 0 60px #0f0;
  }

  40% {
    box-shadow:
      0 0 40px #0f0,
      inset 0 0 40px #0f0;
  }

  60% {
    box-shadow:
      0 0 80px #0f0,
      inset 0 0 80px #0f0;
  }

  80% {
    box-shadow:
      0 0 100px #0f0,
      inset 0 0 100px #0f0;
  }

  100% {
    box-shadow:
      0 0 10px #0f0,
      inset 0 0 20px #0f0;
    filter: hue-rotate(360deg);
  }
}

